followPath(path) {
    if (!path || path.length < 2)
      return;
    this.path = path;
    this.step = 0;
    if (this.following)
      path.pop();
    if (!this.moving && !this.changedPath())
      this.startPathingCallback?.(path);
    this.nextStep();
  }

